def _anchors_path() -> str:
    """Resolve the per-task gt_issue_anchors.json artifact, call-time.
    Priority: GT_ANCHORS_PATH (explicit) -> $GT_CERT_DIR/gt_issue_anchors.json
    (the substrate-consume container mount /gt_artifacts, where the artifact
    actually lives in the live deepswe_full run — the /tmp default never exists
    in the agent container) -> the /tmp default (host/replay)."""
    p = os.environ.get("GT_ANCHORS_PATH")
    if p:
        return p
    cert = os.environ.get("GT_CERT_DIR", "")
    if cert:
        cand = os.path.join(cert, "gt_issue_anchors.json")
        if os.path.isfile(cand):
            return cand
    return "/tmp/gt_issue_anchors.json"


def _load_gt_oracle():
    """Lazy sibling load of gt_oracle.py (the SPEC/obligation producer + the
    distribution-derived gate_pool). Pre-registers THIS module under
    gt_oracle's sibling key so its primitives (_TEST_RUNNER_RE etc.) are
    SHARED, never re-executed. Correct-or-quiet: a missing sibling (gt_oracle
    or its gt_oracle_sense dependency) -> None, no obligation candidates."""
    global _gt_oracle_mod, _gt_oracle_tried
    if _gt_oracle_tried:
        return _gt_oracle_mod
    _gt_oracle_tried = True
    try:
        import importlib.util as _ilu
        sys.modules.setdefault("gt_mini_patch_oracle", sys.modules[__name__])
        here = os.path.dirname(os.path.abspath(__file__))
        path = os.path.join(here, "gt_oracle.py")
        if not os.path.isfile(path):
            return None
        spec = _ilu.spec_from_file_location("gt_oracle_live", path)
        if spec and spec.loader:
            mod = _ilu.module_from_spec(spec)
            sys.modules["gt_oracle_live"] = mod
            spec.loader.exec_module(mod)
            _gt_oracle_mod = mod
    except Exception as _oe:  # noqa: BLE001 -- correct-or-quiet, never break the loop
        # A5 (2026-07-05): DURABLE telemetry — spec.obligation (gt §15.4 "the #1 lever")
        # would otherwise vanish for the WHOLE run with ZERO marker on any channel (the
        # bare swallow). Fire once (module latch) to the harvested ledger + stderr.
        global _gt_oracle_load_reported
        if not _gt_oracle_load_reported:
            _gt_oracle_load_reported = True
            _crash_emit("spec.obligation", _oe)
        _gt_oracle_mod = None
    return _gt_oracle_mod


_oblig_resurface_fired = False

# ═══════════════════════════ GT_OBLIGATIONS_V2 (T3) ══════════════════════════
# Exercised-clause detector. ACTIVATION IS ARTIFACT-WINS: T3 runs iff the T2
# artifact gt_obligations_v2.json exists with obligations_version==2 in
# $GT_CERT_DIR — never from this process's env, so host and container can never
# disagree (split-brain rule). When active it OWNS the VERIFY/SUBMIT obligation
# site: violations-only, SILENT when every checkable clause is exercised
# (correct-or-quiet — silence is the earned outcome, the v1 resurface does NOT
# fall through). Dose: at most 2 emissions per run, deduped by status-vector
# hash. Leak screen identical to the brief side (test-name/F2P regexes +
# persisted render_path_tokens); a leaky row drops whole (fail closed).

_unexercised_emitted: set[str] = set()
_unexercised_late_suppressed: set[str] = set()
_obligations_v2_cache: dict | None = None
_V2_LEAK_TEST_RE = re.compile(r"\b(?:test_[A-Za-z0-9_]+|[A-Za-z0-9_]+_test)\b")
_V2_LEAK_F2P_RE = re.compile(
    r"\b(?:FAIL_TO_PASS|PASS_TO_PASS|fail_to_pass|pass_to_pass)\b"
)


def _load_obligations_v2() -> dict | None:
    """The T2 artifact, cached. None = v2 inactive (v1 resurface owns the site)."""
    global _obligations_v2_cache
    if _obligations_v2_cache is not None:
        return _obligations_v2_cache or None
    data: dict = {}
    try:
        cert = os.environ.get("GT_CERT_DIR", "") or "/tmp"
        with open(os.path.join(cert, "gt_obligations_v2.json"),
                  encoding="utf-8") as fh:
            loaded = json.load(fh)
        if isinstance(loaded, dict) and loaded.get("obligations_version") == 2:
            data = loaded
    except Exception:  # noqa: BLE001 — absent artifact = v2 inactive, never an error
        data = {}
    _obligations_v2_cache = data
    return data or None


class _V2ClauseView:
    __slots__ = (
        "idx", "clause_id", "verbatim", "subject_symbols", "sym_parts", "region",
    )

    def __init__(self, idx: int, clause: dict):
        self.idx = idx
        self.clause_id = str(clause.get("clause_id") or idx)
        self.verbatim = str(clause.get("verbatim_text") or "")
        self.subject_symbols = frozenset(
            s for s in (clause.get("subject_symbols") or ()) if isinstance(s, str)
        )
        self.region = str(clause.get("region") or "normative")
        parts: set[str] = set()
        for s in (clause.get("symbols") or ()):
            if isinstance(s, str):
                parts.add(s)
                parts.update(p for p in s.split(".") if len(p) >= 3)
        self.sym_parts = frozenset(parts)


def _v2_obligation_truth():
    """Authoritative v2 lifecycle over artifact subjects and observed executions."""
    data = _load_obligations_v2()
    if not data:
        return None
    clauses = [c for c in (data.get("clauses") or []) if isinstance(c, dict)]
    if not clauses:
        return None
    try:
        from groundtruth.runtime.obligations import (
            BehavioralProof,
            classify_checked_behavioral_proof,
            classify_exercise_evidence,
            obligation_truth_statuses,
        )
    except Exception:  # noqa: BLE001 — product pkg absent -> quiet
        return None
    views = [_V2ClauseView(i, c) for i, c in enumerate(clauses)]
    exercises = []
    proofs = []
    after_turn_by_id = {}
    for view in views:
        subjects = view.subject_symbols
        after_turn_by_id[view.idx] = _ss_last_relevant_edit_turn(subjects)
        for command, output, returncode, turn in _ss_behavioral_probe_events:
            exercise = classify_exercise_evidence(
                command, output, returncode, subjects, turn=turn,
            )
            if exercise is not None:
                exercises.append(exercise)
            proof = classify_checked_behavioral_proof(
                command, output, returncode, subjects, turn=turn,
            )
            if proof is None and _v2_checked_probe_covers_clause(
                    view, command, output, returncode):
                normalized = frozenset(
                    str(subject).strip().lower()
                    for subject in subjects if str(subject).strip()
                )
                if normalized:
                    proof = BehavioralProof(normalized, int(turn), "checked_live_probe")
            if proof is not None:
                proofs.append(proof)
    return obligation_truth_statuses(
        views,
        _edited_symbols_for_obligations(),
        exercises,
        proofs,
        after_turn_by_id=after_turn_by_id,
    )


def _v2_obligation_result_ready() -> bool:
    """Whether this observation produced clause-scoped execution evidence.

    A custom executable probe is a semantic verification-result boundary even
    when its shell carrier is not a named test runner.  Relevance comes from the
    same exact subject-bound truth projection used by the renderer; an unrelated
    successful command therefore cannot open the obligation delivery gate.
    """
    truth = _v2_obligation_truth()
    if truth is None:
        return False
    return any(
        (
            row.exercise is not None
            and int(row.exercise.turn) == int(_action_count)
        )
        or (
            row.proof is not None
            and int(row.proof.turn) == int(_action_count)
        )
        for row in truth
    )


def _v2_clause_fresh_behavioral_proof(view) -> "dict | None":
    """Leak-safe identity for checked clause proof newer than its last edit."""
    try:
        from groundtruth.runtime.obligations import (
            classify_checked_behavioral_proof,
            obligation_subject_terms,
        )
        subjects = obligation_subject_terms(str(getattr(view, "verbatim", "") or ""))
        if not subjects:
            return None
        last_edit = _ss_last_relevant_edit_turn(subjects)
        for command, output, returncode, turn in _ss_behavioral_probe_events:
            proof = classify_checked_behavioral_proof(
                command, output, returncode, subjects, turn=turn
            )
            proof_turn = int(proof.turn) if proof is not None else int(turn)
            if (proof is None and not _v2_checked_probe_covers_clause(
                    view, command, output, returncode)) or proof_turn <= last_edit:
                continue
            subject_digest = hashlib.sha256(
                "|".join(sorted(subjects)).encode("utf-8")
            ).hexdigest()[:16]
            subject_term_digests = [
                hashlib.sha256(subject.encode("utf-8")).hexdigest()[:16]
                for subject in sorted(subjects)
            ]
            return {
                "clause_id": str(getattr(view, "clause_id", view.idx)),
                "subject_digest": subject_digest,
                "subject_term_digests": subject_term_digests,
                "proof_turn": proof_turn,
                "last_relevant_edit_turn": int(last_edit),
            }
        return None
    except Exception:  # noqa: BLE001 -- proof uncertainty must retain the clause
        return None


_V2_PROOF_PROSE = frozenset({
    "another", "behavior", "does", "expect", "expected", "format", "handled",
    "have", "just", "like", "more", "must", "possibly", "possible", "preserve",
    "requirement", "rules", "should", "support", "supported", "this", "they",
    "true", "false", "useful", "values", "would",
})
_V2_PROOF_TOKEN_RE = re.compile(r"\b[A-Za-z0-9_][A-Za-z0-9_.:-]*\b")


def _v2_proof_terms(text: str) -> "set[str]":
    """Behavior-bearing terms from issue prose for a checked-probe relation test.

    These terms establish only that the executed probe concerns the clause.  Dynamic truth
    still comes from an exact rc=0 plus a checked result shape below; prose overlap alone can
    never retire an obligation.
    """
    return {
        token.lower() for token in _V2_PROOF_TOKEN_RE.findall(text or "")
        if (len(token) >= 4 or any(char.isdigit() for char in token))
        and token.lower() not in _V2_PROOF_PROSE
    }


def _v2_relation_stems(text: str) -> "set[str]":
    """Comparable identifier stems for one evaluated expression.

    The small suffix fold joins ordinary API morphology (``matcher.matches`` to
    ``matching``) without admitting prose elsewhere in the command.
    """
    stems: "set[str]" = set()
    for token in _V2_PROOF_TOKEN_RE.findall(text or ""):
        for part in re.split(r"[.:-]", token.lower()):
            if len(part) < 4:
                continue
            stem = part
            for suffix in ("ing", "ers", "er", "es", "s"):
                if stem.endswith(suffix) and len(stem) - len(suffix) >= 4:
                    stem = stem[:-len(suffix)]
                    break
            stems.add(stem)
    return stems


def _v2_expression_covers_relation(expression: str, relation_terms: "set[str]") -> bool:
    relation_stems = {
        stem for term in relation_terms for stem in _v2_relation_stems(term)
    }
    return bool(relation_stems & _v2_relation_stems(expression))


def _v2_call_derived_output_bindings(
    command: str,
) -> "list[tuple[str, str]] | None":
    """Terms printed from variables assigned call results, excluding static labels.

    The output line is joined to its print statement by the literal prefix preceding
    the result variable.  Only the suffix after that prefix is dynamic evidence; a
    hard-coded expectation in the label/comment cannot prove itself.
    """
    assignments = dict(re.findall(
        r"^\s*([A-Za-z_]\w*)\s*=\s*([A-Za-z_]\w*(?:\.[A-Za-z_]\w*)*\([^\n]*\))\s*$",
        command or "", re.MULTILINE))
    if not assignments:
        return None
    bindings: "list[tuple[str, str]]" = []
    for line in (command or "").splitlines():
        printed = re.search(r"\bprint\s*\((.*)\)\s*(?:#.*)?$", line)
        if not printed:
            continue
        body = printed.group(1)
        for variable in assignments:
            match = re.search(rf"\b{re.escape(variable)}\b", body)
            if not match:
                continue
            prefix_source = body[:match.start()]
            literals = [
                value for _quote, value in re.findall(r"(['\"])(.*?)\1", prefix_source)
            ]
            if literals:
                bindings.append((variable, " ".join(literals)))
            break
    if len(bindings) < 2:
        return None
    return bindings


def _v2_checked_probe_covers_clause(view, command: str, output: str, returncode) -> bool:
    """Conservative fallback for checked native probes outside the core parser's shapes.

    Two generalized shapes are admitted: a >=2-case Boolean call matrix whose observed values
    exactly match inline expectations, or >=2 call-derived printed values covering every
    concrete alternative in a literal requirement.  Both require exact integer rc=0 and a
    command/relation join; arbitrary successful scripts and unrelated GREEN remain ineligible.
    """
    if type(returncode) is not int or returncode != 0 or not command or not output:
        return False
    clause = str(getattr(view, "verbatim", "") or "")
    relation_terms = _v2_proof_terms(clause)

    checked: "list[str]" = []
    for line in command.splitlines():
        marker = re.search(r"#\s*(True|False)\b", line)
        expression = (
            re.search(r"\{([^{}]*\([^{}]*\)[^{}]*)\}", line[:marker.start()])
            if marker else None
        )
        if (marker and expression
                and _v2_expression_covers_relation(expression.group(1), relation_terms)):
            checked.append(marker.group(1))
    observed = re.findall(r":\s*(True|False)\s*$", output, re.MULTILINE)
    if len(checked) >= 2 and observed == checked:
        return True

    bindings = _v2_call_derived_output_bindings(command)
    output_lines = [line for line in output.splitlines() if line.strip()]
    if bindings is None or len(output_lines) < 2:
        return False
    dynamic_output: "list[str]" = []
    for _variable, prefix in bindings:
        matches = [line for line in output_lines if line.strip().startswith(prefix)]
        if len(matches) != 1:
            return False
        suffix = matches[0].strip()[len(prefix):].strip()
        if not suffix:
            return False
        dynamic_output.append(suffix)
    alternatives = [
        _v2_proof_terms(part)
        for part in re.split(r"\b(?:or|possibly|possible)\b", clause, flags=re.IGNORECASE)
    ]
    concrete = [terms for terms in alternatives if any(any(c.isdigit() for c in t) for t in terms)]
    dynamic_term_sets = [
        {
            token.lower()
            for token in _V2_PROOF_TOKEN_RE.findall(observed_value)
        }
        for observed_value in dynamic_output
    ]
    # The requirement alternatives are an allowed-result set, not a coverage
    # checklist.  Every independently evaluated result must belong to that set,
    # but two cases may legitimately resolve to the same alternative (A, A for
    # an "A or B" contract).  Keep each dynamic suffix separate so one valid
    # result cannot launder an unrelated result through a union of output terms.
    return bool(
        len(concrete) >= 2
        and dynamic_term_sets
        and all(
            any(terms <= observed for terms in concrete)
            for observed in dynamic_term_sets
        )
    )


def _v2_partition_fresh_proofs(statuses, *, kind: str, boundary: str):
    """Remove strictly proven clauses and ledger why each produced zero bytes.

    ``CLAUSE_UNVERIFIABLE`` means the static subject-symbol classifier could not exercise the
    clause.  It remains eligible for retirement only when the independent, fresh checked-probe
    path proves it dynamically; absent that proof, its status and rendered bytes are retained.
    """
    if not _ss_late_drop_on():
        return list(statuses or ())
    try:
        from groundtruth.runtime.obligations import (
            CLAUSE_EDITED_UNEXERCISED,
            CLAUSE_UNADDRESSED,
            CLAUSE_UNVERIFIABLE,
        )
        dynamically_provable = {
            CLAUSE_EDITED_UNEXERCISED,
            CLAUSE_UNADDRESSED,
            CLAUSE_UNVERIFIABLE,
        }
    except Exception:  # noqa: BLE001 -- proof uncertainty retains every clause
        return list(statuses or ())
    data = _load_obligations_v2() or {}
    retained = []
    for view, status in statuses or ():
        proof_meta = (
            _v2_clause_fresh_behavioral_proof(view)
            if status in dynamically_provable else None
        )
        if proof_meta is None:
            retained.append((view, status))
            continue
        identity = {
            **proof_meta,
            "artifact_issue_sha256": str(data.get("issue_sha256") or ""),
            "boundary": boundary,
        }
        suppression_key = hashlib.sha256(json.dumps({
            **identity,
            "kind": kind,
            "iteration": int(_action_count),
        }, sort_keys=True).encode("utf-8")).hexdigest()[:16]
        if suppression_key in _unexercised_late_suppressed:
            continue
        _unexercised_late_suppressed.add(suppression_key)
        _runtime_ledger_record(
            kind=kind,
            outcome=_ProductSignalOutcome.SUPPRESSED_HIDDEN_ONLY,
            reason="ss_late",
            extra=identity,
        )
    return retained


def _v2_attribute_proven_truth(rows, *, kind: str, boundary: str) -> None:
    """Record earned silence from the same proof rows used by live rendering.

    G-cluster: the recorded ledger proved this attribution row emitted a PARTIAL identity
    (clause_id + artifact_issue_sha256 + boundary + proof_turn) while the sibling writer
    ``_v2_partition_fresh_proofs`` emitted the FULL identity (also subject_digest +
    subject_term_digests). A suppress_late oracle case that matches on the clause/subject
    digests (``_matches_exact_clause`` / ``_matches_subject``) therefore FAILED against this
    writer's rows. Emit the SAME full identity here — derived EXACTLY as
    ``_v2_clause_fresh_behavioral_proof`` derives it (``obligation_subject_terms`` then the two
    sha256[:16] constructions). Attribution rows only; suppression DECISIONS unchanged;
    model-facing bytes byte-identical."""
    if not _ss_late_drop_on():
        return
    try:
        from groundtruth.runtime.obligations import (
            ObligationTruthState,
            obligation_subject_terms,
        )
    except Exception:  # noqa: BLE001 — attribution must never break delivery
        return
    data = _load_obligations_v2() or {}
    for row in rows or ():
        if row.state is not ObligationTruthState.PROVEN or row.proof is None:
            continue
        clause_id = str(getattr(row.view, "clause_id", row.view.idx))
        subjects = obligation_subject_terms(str(getattr(row.view, "verbatim", "") or ""))
        subject_digest = hashlib.sha256(
            "|".join(sorted(subjects)).encode("utf-8")
        ).hexdigest()[:16]
        subject_term_digests = [
            hashlib.sha256(subject.encode("utf-8")).hexdigest()[:16]
            for subject in sorted(subjects)
        ]
        identity = {
            "clause_id": clause_id,
            "subject_digest": subject_digest,
            "subject_term_digests": subject_term_digests,
            "artifact_issue_sha256": str(data.get("issue_sha256") or ""),
            "boundary": boundary,
            "proof_turn": int(row.proof.turn),
        }
        suppression_key = hashlib.sha256(json.dumps({
            **identity, "kind": kind,
        }, sort_keys=True).encode("utf-8")).hexdigest()[:16]
        if suppression_key in _unexercised_late_suppressed:
            continue
        _unexercised_late_suppressed.add(suppression_key)
        _runtime_ledger_record(
            kind=kind,
            outcome=_ProductSignalOutcome.SUPPRESSED_HIDDEN_ONLY,
            reason="ss_late",
            extra=identity,
        )


def _v2_attribute_resurface_silence() -> None:
    """Account for earned V2 silence at the retired post-edit resurface boundary."""
    if not _ss_late_drop_on():
        return
    truth = _v2_obligation_truth()
    if truth is not None:
        _v2_attribute_proven_truth(
            truth, kind="obligation.resurface", boundary="post_edit")


def _unexercised_clause_candidate() -> tuple[float, str] | None:
    """T3 candidate for the VERIFY/SUBMIT site (see block comment above)."""
    if _GT_BASELINE or len(_unexercised_emitted) >= 2:
        return None
    truth = _v2_obligation_truth()
    if truth is None:
        return None
    data = _load_obligations_v2() or {}
    _v2_attribute_proven_truth(
        truth, kind="obligation.unexercised", boundary="test_result")
    try:
        from groundtruth.runtime.obligations import render_obligation_truth_block
    except Exception:  # noqa: BLE001
        return None
    path_tokens = [
        t.lower() for t in (data.get("render_path_tokens") or ())
        if isinstance(t, str) and len(t) >= 3
    ]

    def _leaky(row: str) -> bool:
        if _V2_LEAK_TEST_RE.search(row) or _V2_LEAK_F2P_RE.search(row):
            return True
        low = row.lower()
        return any(t in low for t in path_tokens)

    block = render_obligation_truth_block(truth, max_listed=6, leak_screen=_leaky)
    if not block:
        return None
    vec = hashlib.sha256(
        "|".join(
            f"{getattr(row.view, 'idx', '')}:{row.state.value}" for row in truth
        ).encode("utf-8")
    ).hexdigest()[:8]
    if vec in _unexercised_emitted:
        return None
    _unexercised_emitted.add(vec)
    # SM-5 F (#50): under the global arbiter, attach the rollback that un-burns THIS
    # status-vector emission so a pool LOSER (0 bytes) defers instead of destroying the
    # unexercised-clause block. Guarded -> byte-identical no-op when the arbiter is off.
    _arm_lane_a_rearm("obligation.unexercised", lambda v=vec: _unexercised_emitted.discard(v))
    return (0.9, block)


def _payload_leaks_test_identity(text: str) -> bool:
    """Shared leak predicate for the model-facing delivery paths (Seam-F1/F2, bounce
    2026-07-10): True iff ``text`` carries a test path / ``::nodeid`` / ``def test_``
    echo — the seam-owned ABI §5 predicate ``native_render.contains_test_identity``.
    Fail-open (engine import-absent -> False), identical to the ``_gt_deliver_append``
    chokepoint, so a leak-free payload is byte-identical and the in-container path (GT
    code synced) always screens."""
    try:
        from groundtruth.runtime.native_render import contains_test_identity
        return bool(contains_test_identity(text))
    except Exception:  # noqa: BLE001 — engine absent in-container: preserve behavior
        return False


# Seam-F2b + Fable-LIPI round-2 (2026-07-11): the PROSE leak screen is SINGLE-SOURCED with the
# brief via `native_render.PROSE_TEST_NAME_RE`/`PROSE_ASSERT_RE` (the canonical pair) so the two
# model-facing prose surfaces cannot drift — round-1 tuned each separately and each missed a
# different half (case+underscore Test_/TEST_, rust assert_eq!/crate::tests::/#[test], JS/TS
# .test.ts, and the seam had NO assert leg at all). The local mirrors below are ONLY the
# fail-open fallback for a broken in-container import (native_render is ship-listed, so normally
# unused); `test_prose_screen_parity_with_native_render` pins them equal to the canonical.
_PROSE_TEST_NAME_RE = re.compile(
    r"(?i:\btest_\w+\b)|(?i:\b\w+_test\b)|\bTest[A-Z]\w*\b|\btest[A-Z]\w*\b"
    r"|\b\w[\w.\-]*\.(?:test|spec)\.(?:ts|tsx|js|jsx|mjs|cjs)\b"
    r"|[\w/\\+\-]+\.[A-Za-z0-9_]+::[\w.\[\]\-]+|\b\w+::tests?::\w|\btests?[\\/]|\#\[\s*tests?\b"
    r"|\b(?:it|describe|context)\(\s*['\"]")
_PROSE_ASSERT_RE = re.compile(r"\bassert(?:_\w+|[A-Z]\w*|!|\s*\()")


def _prose_leaks_test_identity(text: str) -> bool:
    """PROSE-payload leak screen. ``contains_test_identity`` (via ``_payload_leaks_test_identity``)
    is a runner-TRANSCRIPT belt-check (nodeid / test-file path / ``def test_`` echo, correct there
    because ``_strip_case_tokens``/``_final_scrub`` scrub bare names). ISSUE PROSE is NOT a scrubbed
    transcript, so a SWE-bench issue naming a failing test / assertion by its BARE token sails onto
    the model-facing surface at the submit decision point. This adds the language-complete bare-name
    + assertion screen, SINGLE-SOURCED with the brief through ``native_render.prose_leaks_test_identity``
    so neither surface leaks a class the other catches. SCOPE: prose-bearing producers only
    (obligation-resurface) — NEVER structured Lane-A facts, whose legitimate ``test``/``Test``
    substrings would over-drop; those stay on ``_payload_leaks_test_identity``. Fail-open on
    import-absent -> the pinned local mirror still screens."""
    if _payload_leaks_test_identity(text):
        return True
    try:
        from groundtruth.runtime.native_render import prose_leaks_test_identity
        return bool(prose_leaks_test_identity(text))
    except Exception:  # noqa: BLE001 — engine absent in-container: local mirror still screens
        t = text or ""
        return bool(_PROSE_TEST_NAME_RE.search(t) or _PROSE_ASSERT_RE.search(t))


def _obligation_resurface_candidate() -> tuple[float, str] | None:
    """PRE-SUBMIT obligation re-surfacing (Cursor-principled INSIGHT, 2026-06-23).
    The issue's requirements were delivered once in the brief; by the near-submit
    turn they are thousands of lines stale, so the agent sees GREEN LOCAL TESTS and
    concludes "done" without re-checking the requirement -- the false-confident-
    submit shape (cattrs/adaptix: 849/2812 local passed, hidden requirement missed).
    This re-states the obligations as the decision-moment checklist, EASING the
    agent's reasoning ("did I actually handle each?"). GT does NOT verify the patch
    or run anything -- it hands back the ammo the agent had lost. Deterministic
    (obligations already extracted), correct-or-quiet (no obligations -> None),
    fires ONCE. NOT coverage-gated: passing local tests does not prove an obligation
    met, so this fires regardless of edited/tested status."""
    # C6 (2026-07-04): READ the fire-once latch (guard below) but never SET it here.
    # The old code latched at PRODUCTION (before _lane_a_deliver); a cross-lane dedup
    # skip then burned the latch with NO delivery and it was NOT in the re-arm set,
    # permanently silencing a later DISTINCT resurface. The latch is consumed ONLY on
    # a real DELIVERED outcome in _lane_a_deliver (same law as l3.cochange, bug #5).
    if _oblig_resurface_fired or _GT_BASELINE:
        return None
    lines: list[str] = []
    seen: set[str] = set()
    # Primary: the structured obligations[] (the extractor's output, when present).
    om = _load_gt_oracle()
    if om is not None:
        try:
            for o in (om.load_obligations(_anchors_path()) or []):
                t = str(o.get("verbatim_text") or "").strip().replace("\n", " ")
                # Seam-F2 (LEAK LAW): the obligation's verbatim_text quotes issue
                # sentences, which routinely NAME the failing grader test. Screen each
                # line through the PROSE screen (Seam-F2b: catches BARE names, not just
                # transcript nodeids) — drop a leaky obligation (defense-in-depth; F1 also
                # drop-wholes the payload on the transcript class, but correct-or-quiet at
                # the producer keeps the clean obligations deliverable).
                if t and t not in seen and not _prose_leaks_test_identity(t):
                    seen.add(t)
                    lines.append("  - %s" % (t[:160]))
                if len(lines) >= 6:
                    break
        except Exception:  # noqa: BLE001 — correct-or-quiet
            lines = []
    # Fallback: the structured array is empty for tasks the extractor cannot
    # decompose into obligations. Re-surface the
    # ISSUE TEXT itself -- the requirement GT already holds, written into the
    # substrate as issue.txt. Deterministic, no pattern-extraction (no
    # benchmaxxing): the first paragraph (the core requirement statement), compact.
    if not lines:
        for cand in (os.path.join(os.environ.get("GT_CERT_DIR", "/gt_artifacts"), "issue.txt"),
                     os.environ.get("GT_ISSUE_FILE", "")):
            if not cand or not os.path.exists(cand):
                continue
            try:
                txt = open(cand, encoding="utf-8", errors="replace").read().strip()
            except Exception:  # noqa: BLE001 — unreadable is not a signal
                continue
            if not txt:
                continue
            para = txt.split("\n\n")[0].strip().replace("\n", " ")
            # Seam-F2 (LEAK LAW): issue.txt is baked into $GT_CERT_DIR and SWE-bench
            # issues routinely name the failing test — screen the fallback paragraph through
            # the PROSE screen (Seam-F2b: BARE names too). A leaky paragraph drops WHOLE
            # (correct-or-quiet: no resurface this task).
            if len(para) >= 20 and not _prose_leaks_test_identity(para):
                lines = ["  - %s" % para[:400]]
                break
    if not lines:
        return None
    # NOTE: latch intentionally NOT set here (see C6 note above) — it is consumed on
    # the DELIVERED outcome inside _lane_a_deliver.
    # W10 ITEM-3 completion (2026-07-13, 2-task-smoke finding m93): this site shipped the ONE
    # remaining tagged observation on the sh-744 canary — route through _nudge_native.
    return (_SEV_OBLIGATION,
            _nudge_native(
                "\n<gt-nudge reason=\"obligation_resurface\">\nGT: before you submit, the "
                "issue requires the following -- re-read it against your patch and confirm "
                "it is handled (passing local tests does NOT prove the requirement is met):\n%s\n"
                "</gt-nudge>" % "\n".join(lines),
                kind="obligation.resurface"))


def _obligation_nudge_block() -> tuple[float, str] | None:
    """SPEC producer at the live review transition — delivery-engine STAGE 2
    (2026-06-11): the per-obligation STATUS checklist (gt_gt §15.4 Stage 3 /
    DEEP_TRAJECTORY §3.3 fix #1, the #1 lever).

    WHAT: every unmet obligation with its sensed status — `[✓ edited, ✗
    untested]` / `[✗ not addressed]` — issue text verbatim, the covering test
    named per untested obligation (graph.db assertions, FACT-tier only).
    WHEN: every review-transition turn whose status VECTOR is new (the
    content×phase×status dedup; same vector -> suppress, changed -> re-fire).
    TRIGGER (hybrid, 4 composited signals): review transition (>=1 edit +
    >=3 non-edit) ∧ >=1 obligation edited-but-untested (the proven-aimed
    intersection — 3/3 named the hidden verifier's target, LEGITIMACY §1.5)
    ∧ unmet obligations exist ∧ status vector unseen.
    SEVERITY (computed, never a constant): composite_severity(base=5,
    budget_fraction, unmet_ratio) — Zilberstein-form urgency.
    Correct-or-quiet: no sibling module / no obligations / nothing
    edited-untested / vector already delivered -> None.

    Returns (severity, payload) or None."""
    global _oracle_obligation_fired, _oblig_status_last_hash, _oblig_final_shot_fired
    om = _load_gt_oracle()
    if om is None:
        return None
    try:
        obls = om.load_obligations(_anchors_path())
        if not obls:
            return None
        tracker = _get_obligation_tracker(om)
        _obl_edited = _edited_symbols_for_obligations()  # P1(d): span-augmented
        tracker.update(
            _obl_edited, _oracle_tested_tokens, _action_count)
        # O-2 (flag GT_OBLIGATION_FRESHNESS): the freshness-demotion CONTROL RECORD
        # no longer lives here. It was dark on every V2 run because this legacy block
        # is only reached when V2 obligations are ABSENT (see _review_obligation_candidate).
        # It now fires from _emit_obligation_freshness_control(om), called at the TOP of
        # _review_obligation_candidate BEFORE the V2/legacy dispatch, so the record is
        # gradeable on both producers. Observability-only: the legacy tracker it drives is
        # not the V2 delivery path, and this function's own tracker.update() (above) still
        # sets the statuses this checklist renders. Default-off => no-op, byte-identical.
        _persist_obligation_status(tracker)
        statuses = tracker.statuses_tuple(
            _obl_edited, _oracle_tested_tokens)
        unmet = om.order_unmet(statuses)
        if not unmet:
            return None
        # Precision gate: fire only when >=1 obligation is EDITED-but-untested
        # (the intersection that demonstrably aims at the verifier's target);
        # unaddressed obligations ride along as checklist rows, never trigger
        # alone (edit tokens are a noisy proxy — correct-or-quiet).
        if not any(s == om.OBL_EDITED_UNTESTED for _v, s, _t, _c in unmet):
            return None
        h = om.status_vector_hash(statuses)
        # Near budget end (>80% steps spent), give the obligation ONE final shot
        # even if the status vector hasn't changed (the agent may never have
        # tested, so the hash is the same as the early fire). R3 FLOOD fix: this
        # end-of-budget shot fires exactly ONCE per run. Without the one-shot latch
        # the discard re-armed every turn past 80% AND the rotating status vector
        # produced fresh hashes -> the ~5.1KB checklist re-fired every turn.
        budget_b_now = (_action_count / _GT_STEP_LIMIT) if _GT_STEP_LIMIT else 0.0
        _final_shot = budget_b_now > 0.80
        if _final_shot:
            if _oblig_final_shot_fired:
                return None  # one-shot: the end-of-budget checklist already fired
            _oblig_status_emitted.discard(h)  # re-arm this single vector for the shot
        if h in _oblig_status_emitted:
            return None
        # ── COVERING-TEST per untested obligation (Stage B query, FACT-tier
        # CALLS edges only). Render all unmet rows; attach the EXISTENCE of a
        # graph-linked covering test when the query returns one. E5 (2026-07-05):
        # the payload carries NO test name/run_cmd, so the renderer emits a
        # generic "run your targeted tests" line, never a test identifier.
        covering: dict[int, dict] = {}
        for v, s, touched, _conf in unmet:
            if s != om.OBL_EDITED_UNTESTED:
                continue
            try:
                hits = _covering_tests_for_symbols(set(touched))
                if hits:
                    covering[v.idx] = hits[0]
            except Exception:  # noqa: BLE001 -- enrichment is best-effort
                pass
        # R3 FLOOD fix: cap the number of obligations rendered per emission
        # (render_obligation_status_block truncates + appends a "(+N more)" line).
        payload = om.render_obligation_status_block(
            statuses, covering, max_listed=_OBLIG_MAX_LISTED)
        if not payload:
            return None
        # production-time latch: delivered-vector set; a gate LOSS releases it
        # (deferred, not destroyed — the established re-arm law).
        _oblig_status_emitted.add(h)
        _oblig_status_last_hash = h
        _oracle_obligation_fired = True
        # R3: burn the one-shot end-of-budget latch on the actual fire so the
        # past-80% checklist can never re-arm/re-fire on a later turn.
        if _final_shot:
            _oblig_final_shot_fired = True
        budget_b_sev = (_action_count / _GT_STEP_LIMIT) if _GT_STEP_LIMIT else 0.0
        unmet_ratio = len(unmet) / max(len(statuses), 1)
        sev = om.composite_severity(_SEV_OBLIGATION, budget_b_sev, unmet_ratio)
        # D3 fix: pre-submit boost uses composite so it BEATS horizon gate.
        # Horizon: composite(_SEV_GATE, budget, tcov) ≈ 7.8-8.9.
        # Obligation: composite(_SEV_GATE+1, budget, unmet) ≈ 9.0+ → always wins.
        if budget_b_sev > 0.90 and unmet:
            sev = om.composite_severity(_SEV_GATE + 1, budget_b_sev, unmet_ratio)
        # Also drop the nonedit_streak requirement in the final 10% — the agent
        # may be editing right up to submit and still needs the checklist.
        return (sev, payload)
    except Exception:  # noqa: BLE001 -- never break the agent loop
        return None


def _emit_obligation_freshness_control(om) -> None:
    """O-2 (GT_OBLIGATION_FRESHNESS, CAP.eligibility) — emit the freshness-demotion
    CONTROL RECORD at the review boundary, INDEPENDENT of which producer owns delivery
    this turn (V2 ``obligation.unexercised`` OR legacy ``spec.obligation``).

    Why this exists as a standalone: the record used to live inside
    ``_obligation_nudge_block``, which ``_review_obligation_candidate`` SKIPS whenever V2
    obligations are present — so the feature was 100%-dark on every V2 run. Lifting it here
    fires it on the GENERAL condition (a legacy obligation tracker exists and this turn
    carries NEW edits vs the last-seen edit set), never keyed on any task/repo/id.

    The V2 branch never constructs the legacy tracker, so this helper builds/reuses it via
    ``_get_obligation_tracker(om)`` and keeps it current with ``tracker.update`` — otherwise
    a genuine stale-edit-after-test could never be sensed on a V2 run. This is
    observability-only and additive: the legacy tracker is NOT the V2 delivery path, so
    ``obligation.unexercised`` bytes are untouched. Default-off (flag) => a pure no-op, so
    flag-off delivery stays byte-identical. Correct-or-quiet: no oracle / no obligations /
    any fault -> silent."""
    if not _obligation_freshness_on():
        return
    global _prev_obl_edited
    try:
        obls = om.load_obligations(_anchors_path())
        if not obls:
            return
        tracker = _get_obligation_tracker(om)
        _obl_edited = _edited_symbols_for_obligations()  # P1(d): span-augmented
        # Keep the legacy tracker current even on a V2 run (the V2 branch never updates
        # it) so apply_edit_freshness can tell a stale post-test edit from a pre-test one.
        tracker.update(_obl_edited, _oracle_tested_tokens, _action_count)
        # The per-turn NEW edits (cumulative delta) are the freshness signal; the
        # cumulative set alone would demote on the pre-test edit too.
        _new_edits = set(_obl_edited) - _prev_obl_edited
        _freshness_transitions = []
        _freshness_error = None
        if _new_edits:
            try:
                _freshness_transitions = tracker.apply_edit_freshness(
                    _new_edits, _action_count)
            except Exception as exc:  # noqa: BLE001 — freshness never breaks the path
                _freshness_error = exc
        _control_participation_record(
            "GT_OBLIGATION_FRESHNESS",
            "mini_seam.obligation_nudge.freshness_demotion",
            ("ERROR" if _freshness_error is not None else
             "APPLIED" if _freshness_transitions else "NO_EFFECT"),
            reason=((f"freshness_error:{type(_freshness_error).__name__}"
                     if _freshness_error is not None else
                     "tested_obligation_demoted" if _freshness_transitions
                     else "no_stale_tested_obligation")),
        )
        _prev_obl_edited = set(_obl_edited)
    except Exception:  # noqa: BLE001 — observability must never break the review path
        return


def _review_obligation_candidate():
    """Select the review-boundary producer and its delivery class.

    V2 keeps its honest ``obligation.unexercised`` identity and Lane-A semantics;
    the legacy status checklist remains a ``spec.obligation`` steer.
    """
    # O-2: fire the GT_OBLIGATION_FRESHNESS control BEFORE the producer dispatch so it is
    # gradeable on the V2 path too (the legacy _obligation_nudge_block, its old home, is
    # unreachable when V2 obligations are present). Observability-only; never blocks dispatch.
    om = _load_gt_oracle()
    if om is not None:
        try:
            _emit_obligation_freshness_control(om)
        except Exception:  # noqa: BLE001 — observability never blocks the producer
            pass
    if _load_obligations_v2() is not None:
        return (
            "obligation.unexercised",
            _unexercised_clause_candidate(),
            True,
        )
    return "spec.obligation", _obligation_nudge_block(), False


# Kinds the gate suppressed THIS turn as a re-armable loss (outranked /
# irrelevant — NOT 'delivered'): _augment_output releases their producers'
# production-time latches so a one-shot class is DEFERRED to a later turn,
# never destroyed (LIPI 2026-06-10: the first-edit contract permanently ate
# the cochange completeness signal; a sev-tie scope block could permanently
# eat the failure_persisted nudge).
_oracle_last_losers: set[str] = set()
_BLOCK_TOKEN_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")

# severity ranks (the plan §3.4 WHAT ordering, mirrored from gt_oracle):
#   6 = verification gate (NEW MAX RANK — budget-critical self-verify),
#   5 = issue-verbatim obligation (the un-misdirectable class),
#   4 = verification-gap nudge, 3 = edit-bound contract, 2 = stuck nudge /
#   review-time scope completeness, 1 = code-map narration (evidence/cochange).
_SEV_GATE = 6           # verification horizon GATE band (displaces everything)
_SEV_OBLIGATION = 5
_SEV_NUDGE_VERIFY = 4
_SEV_CONTRACT = 3
_SEV_STUCK = 2
_SEV_SCOPE = 2
_SEV_CODEMAP = 1
# SM-10 (2026-07-12): the typed recovery nudge is the LADDER FLOOR — it defers to every
# higher-signal producer (contract/obligation/verify/stuck/loop) and only wins the <=1
# dose when it is the sole candidate (or nothing higher fired). "Rank 10": lowest tier.
_SEV_RECOVERY = 1


# ---------------------------------------------------------------------------
# CP013 — phase detection + policy filter (P5 symbol narrowing).
# ---------------------------------------------------------------------------
_pp_dir = os.path.dirname(os.path.abspath(__file__))
if _pp_dir not in _sys.path:
    _sys.path.insert(0, _pp_dir)
try:
    from phase_policy import (
        PHASE_POLICY as _PHASE_POLICY,
        Event,  # type: ignore[assignment]  # real type; enum fallback below is the stub
        Phase,  # type: ignore[assignment]  # real type; enum fallback below is the stub
        phase_allows as _phase_allows_policy,  # type: ignore[assignment]  # real fn; fallback below is the stub
        should_emit as _phase_should_emit,  # type: ignore[assignment]  # real fn; fallback below is the stub
    )
except ImportError:
    # Fallback: no phase filtering — all candidates pass (pre-CP013 behavior)
    import enum as _pp_enum
    class Phase(_pp_enum.Enum):
        ORIENT = "orient"
        VIEW = "view"
        EDIT = "edit"
        VERIFY = "verify"
        SUBMIT = "submit"
    class Event(_pp_enum.Enum):
        TASK_START = "task_start"
        POST_VIEW = "post_view"
        POST_EDIT = "post_edit"
        TEST_RESULT = "test_result"
        REVIEW_TRANSITION = "review_transition"
        PRE_SUBMIT = "pre_submit"
    _PHASE_POLICY = {}
    class _PolicyDecision:
        allowed = True
        reason = "fallback"
    def _phase_allows_policy(kind, phase, policy=None): return True
    def _phase_should_emit(kind, phase, **kw): return _PolicyDecision()


def _detect_phase() -> Phase:
    # bug #4(b): feed test evidence into the trajectory state so derive_phase can
    # reach VERIFY on the FIRST observed test (derive_phase: nonedit_streak >= 3 OR
    # test_count). Omitting test_count pinned a test turn at EDIT and the verify-
    # axis steers were phase-dropped exactly when they should fire.
    state = _ProductTrajectoryState(
        action_count=_action_count,
        step_limit=_GT_STEP_LIMIT,
        edited_files=set(_oracle_edited_rels),
        source_edit_count=_source_edit_count,
        nonedit_streak=_oracle_nonedit_streak,
        test_count=_oracle_test_count,
        test_evidence_seen=_oracle_test_evidence_seen,
    )
    return _product_derive_phase(state)  # type: ignore  # stub infers None; real impl returns Phase


def _phase_allows(kind: str, phase: Phase) -> bool:
    return _phase_allows_policy(kind, phase, _PHASE_POLICY)


def _current_event_for_cmd(cmd: str) -> Event | None:
    """bug #4(a): a real test-runner command IS a TEST_RESULT event (mirrors
    trajectory_state.command_event). The verify-axis steers are event-bound to
    TEST_RESULT; without recognizing it the test turn classified as POST_VIEW/
    POST_EDIT (or nothing) and the steers were dropped as wrong_phase."""
    if cmd and _TEST_RUNNER_RE.search(cmd):
        return Event.TEST_RESULT
    return None


def _current_event(kind: str | None, cmd: str = "") -> Event | None:
    # bug #4(a): a test-runner command is a TEST_RESULT event REGARDLESS of how
    # the bash classifier labelled it (a `pytest …` line carries no edited/viewed
    # file, so _classify often returns neither post_view nor post_edit).
    _te = _current_event_for_cmd(cmd)
    if _te is not None:
        return _te
    if kind == "post_view":
        return Event.POST_VIEW
    if kind == "post_edit":
        return Event.POST_EDIT
    if _oracle_nonedit_streak >= 3 and _oracle_edited_rels:
        return Event.REVIEW_TRANSITION
    if _detect_phase() == Phase.SUBMIT:
        return Event.PRE_SUBMIT
    return None


