_obligation_tracker = None
_obligation_tracker_anchors: str | None = None
# O-2: cumulative edited-symbol set as of the PREVIOUS obligation update — the per-turn
# NEW edits (delta) feed the freshness demotion (a symbol edited AFTER its test).
_prev_obl_edited: set = set()


def _obligation_freshness_on() -> bool:
    """O-2 freshness demotion arm (flag GT_OBLIGATION_FRESHNESS). Default-OFF (byte-
    identical live: the obligation path has documented early-fire fragility, so the
    stale-PASS->EDITED demotion — which can re-arm the resurface nudge — ships behind a
    flag until measured). Never active on the baseline arm."""
    if _GT_BASELINE:
        return False
    return os.environ.get("GT_OBLIGATION_FRESHNESS", "").strip().lower() not in (
        "", "0", "false", "no", "off")


def _get_obligation_tracker(om):
    global _obligation_tracker, _obligation_tracker_anchors
    path = _anchors_path()
    if _obligation_tracker is None or _obligation_tracker_anchors != path:
        obls = om.load_obligations(path)
        _obligation_tracker = om.ObligationTracker(obls)
        _obligation_tracker_anchors = path
    return _obligation_tracker


def _persist_obligation_status(tracker, *, turn: int | None = None) -> None:
    """Write obligation vector to disk + oracle jsonl (P1-18/19)."""
    try:
        import json as _j

        snap = {
            "event": "obligation_status",
            "turn": turn if turn is not None else _action_count,
            "coverage_ratio": float(f"{tracker.coverage_ratio():.8f}"),
            "obligations": tracker.snapshot(),
        }
        # GT_OBLIGATIONS_V2: attach the exercised-clause coverage summary when
        # the T2 artifact is active. Delivery and metrics consume the same truth
        # rows, so a failed exercise cannot be rendered one way and aggregated
        # another way.
        try:
            _truth = _v2_obligation_truth()
            if _truth is not None:
                from groundtruth.runtime.obligations import obligation_truth_summary
                snap["coverage_v2"] = obligation_truth_summary(_truth)
        except Exception:  # noqa: BLE001 — telemetry must never break the loop
            pass
        path = os.environ.get("GT_OBLIGATION_STATUS", "/tmp/gt/obligation_status.json")
        parent = os.path.dirname(path)
        if parent:
            os.makedirs(parent, exist_ok=True)
        with open(path, "w", encoding="utf-8") as fh:
            _j.dump(snap, fh, indent=2)
            fh.write("\n")
        ev = os.environ.get("GT_ORACLE_EVENTS", "/tmp/gt_oracle_events.jsonl")
        with open(ev, "a", encoding="utf-8") as fh:
            fh.write(_j.dumps(snap) + "\n")
    except Exception as exc:  # noqa: BLE001 -- telemetry must never break the loop
        _attestation_persist_failure_row("obligation_status", "", exc)


def _maybe_persist_obligation_status() -> None:
    om = _load_gt_oracle()
    if om is None:
        return
    try:
        obls = om.load_obligations(_anchors_path())
        if not obls:
            return
        tracker = _get_obligation_tracker(om)
        tracker.update(_edited_symbols_for_obligations(),  # P1(d): span-augmented
                       _oracle_tested_tokens, _action_count)
        _persist_obligation_status(tracker)
    except Exception:  # noqa: BLE001
        pass


